import{_ as e,o as t,c as i,a4 as s}from"./chunks/framework.vNSRaLQv.js";const b=JSON.parse('{"title":"TFTP 刷机与 Recovery 恢复","description":"","frontmatter":{"title":"TFTP 刷机与 Recovery 恢复","date":"2026-07-25T00:00:00.000Z"},"headers":[],"relativePath":"posts/08_tftp_and_recovery.md","filePath":"posts/08_tftp_and_recovery.md"}'),o={name:"posts/08_tftp_and_recovery.md"};function l(d,a,r,n,h,c){return t(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="tftp-刷机与-recovery-恢复" tabindex="-1">TFTP 刷机与 Recovery 恢复 <a class="header-anchor" href="#tftp-刷机与-recovery-恢复" aria-label="Permalink to &quot;TFTP 刷机与 Recovery 恢复&quot;">​</a></h1><h2 id="tftp-网络刷机尝试" tabindex="-1">TFTP 网络刷机尝试 <a class="header-anchor" href="#tftp-网络刷机尝试" aria-label="Permalink to &quot;TFTP 网络刷机尝试&quot;">​</a></h2><h3 id="目的" tabindex="-1">目的 <a class="header-anchor" href="#目的" aria-label="Permalink to &quot;目的&quot;">​</a></h3><p>通过 u-boot 的 <code>tftpboot</code> 命令从电脑下载 boot.img 到内存，然后写入 eMMC。</p><h3 id="环境准备" tabindex="-1">环境准备 <a class="header-anchor" href="#环境准备" aria-label="Permalink to &quot;环境准备&quot;">​</a></h3><ol><li>电脑安装 TFTP 服务器：<code>sudo apt install tftpd-hpa</code></li><li>配置 <code>/etc/default/tftpd-hpa</code>：<code>TFTP_DIRECTORY=&quot;/srv/tftp&quot;</code></li><li>放入 boot.img：<code>cp boot.img /srv/tftp/</code></li><li>启动：<code>sudo systemctl start tftpd-hpa</code></li></ol><h3 id="踩坑-tftp-传输超时" tabindex="-1">踩坑：TFTP 传输超时 <a class="header-anchor" href="#踩坑-tftp-传输超时" aria-label="Permalink to &quot;踩坑：TFTP 传输超时&quot;">​</a></h3><p>u-boot 输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Loading: T #T #T ##T ##########T ########T ###T ######T ######T ##T #########</span></span>
<span class="line"><span>Retry count exceeded; starting again</span></span></code></pre></div><p><code>T</code> 表示超时重传。传输失败。</p><h3 id="原因分析" tabindex="-1">原因分析 <a class="header-anchor" href="#原因分析" aria-label="Permalink to &quot;原因分析&quot;">​</a></h3><ol><li><strong>防火墙</strong>：TFTP 使用 UDP 69 端口，数据传输用随机高端口，防火墙可能拦截</li><li><strong>权限</strong>：<code>in.tftpd</code> 需要 root 权限绑定 69 端口</li><li><strong>服务冲突</strong>：systemd 的 tftpd-hpa 和手动启动的 in.tftpd 冲突</li></ol><h3 id="尝试的解决方案" tabindex="-1">尝试的解决方案 <a class="header-anchor" href="#尝试的解决方案" aria-label="Permalink to &quot;尝试的解决方案&quot;">​</a></h3><ul><li><code>sudo iptables -F</code> 清防火墙 — 无效</li><li>手动启动 <code>sudo in.tftpd --listen --secure /srv/tftp</code> — 端口冲突</li><li>Python 实现 TFTP 服务器 — 同样超时</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>TFTP 方案未成功。原因可能是网络驱动在 u-boot 下不稳定，或 TFTP 协议实现问题。</p><h2 id="recovery-恢复" tabindex="-1">Recovery 恢复 <a class="header-anchor" href="#recovery-恢复" aria-label="Permalink to &quot;Recovery 恢复&quot;">​</a></h2><h3 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h3><p>u-boot 中执行 <code>safe</code> 命令进入 recovery 模式。</p><h3 id="恢复步骤" tabindex="-1">恢复步骤 <a class="header-anchor" href="#恢复步骤" aria-label="Permalink to &quot;恢复步骤&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 在 recovery shell 中</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">dd</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> if=/data/local/boot_patched.img</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> of=/dev/block/boot</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> bs=</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;">4096</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">sync</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">reboot</span></span></code></pre></div><h3 id="关键点" tabindex="-1">关键点 <a class="header-anchor" href="#关键点" aria-label="Permalink to &quot;关键点&quot;">​</a></h3><ul><li><code>/data/local/boot_patched.img</code> 在 data 分区，不会被 boot.img 覆盖</li><li><code>dd</code> 直接写 boot 分区，偏移由分区表决定</li><li><code>sync</code> 确保写入完成</li></ul><h3 id="成功恢复" tabindex="-1">成功恢复 <a class="header-anchor" href="#成功恢复" aria-label="Permalink to &quot;成功恢复&quot;">​</a></h3><p>使用 CMA32MB 版本的 boot_patched.img 恢复成功，系统正常启动。</p>`,25)])])}const f=e(o,[["render",l]]);export{b as __pageData,f as default};
